// Clipper2D library is assumed to be available for polygon operations
using namespace Clipper2D;

std::vector<PolygonWithHoles2d> result;
Clipper<IntPoint> clipper;
clipper.AddPolygon(P1.GetPoints(), ptSubject);
clipper.AddPolygon(P2.GetPoints(), ptClip);

Polygons<IntPoint> solution;
clipper.Execute(ctDifference, solution, pftNonZero, pftNonZero);

for (const auto& poly : solution) {
    PolygonWithHoles2d newPoly;
    for (const auto& point : poly) {
        newPoly.AddPoint(std::make_pair(static_cast<double>(point.X),
                                       static_cast<double>(point.Y)));
    }
    result.push_back(newPoly);
}

// Handle holes if any (Clipper2D returns them as separate polygons)
for (size_t i = 0; i < solution.size(); ++i) {
    if (solution[i].size() > 1) {  // Skip if it's a hole (size > 1 indicates outer ring)
        PolygonWithHoles2d outerPoly;
        for (const auto& point : solution[i]) {
            outerPoly.AddPoint(std::make_pair(static_cast<double>(point.X),
                                             static_cast<double>(point.Y)));
        }
        result.push_back(outerPoly);
    }
}

// END_CODE

